=== rt_unaligned_lh.S ===
// rt_unaligned_lh.S
//
// Tier-1 fixture: halfword/byte loads at unaligned addresses inside the
// vsim ROI. Stresses the LSU on byte- and halfword-granular paths that
// the existing fixtures (which only do doubleword sd/ld) never touch.
//
// Phase A (QEMU1): slti x0, x0,  0x5A0 -> drain & exit.
// Phase B (vsim):
//   sd  0x8070605040302010 -> [0x00003000]   (LE: byte[0]=0x10, ..., byte[7]=0x80)
//   lh  t2, 1(t0)   -> 0x3020 (sign-ext positive)
//   lb  t2, 3(t0)   -> 0x40   (sign-ext positive)
//   lhu t2, 5(t0)   -> 0x7060 (unsigned)
//   x10 = 0x3020 + 0x40 + 0x7060 = 0xA0C0
// Phase C (QEMU2): verify x10 == 0xA0C0; exit 0 on PASS, 1 on FAIL.

#include "semihost_exit.inc"

.section .text
.globl _start
_start:
    slti   x0, x0,  0x5A0                 // QEMU1 drains, exits

=== rt_sign_bits.S ===
// rt_sign_bits.S
//
// Tier-1 fixture: 64-bit width fidelity through DM Abstract Commands.
// A bug that truncates or sign-extends incorrectly between the 32-bit
// data0/data1 halves would corrupt the high bits.
//
// Phase A (QEMU1): seed x10..x14 with edge-case 64-bit constants.
// Phase B (vsim):  no-op (just bridges trigger entry/exit).
// Phase C (QEMU2): verify each value; exit code = first mismatching reg num,
//                  or 0 on full pass.

#include "semihost_exit.inc"

.section .text
.globl _start
_start:
    li      x10, 0
    li      x11, -1
    li      x12, 0x8000000000000000
    li      x13, 0x7FFFFFFFFFFFFFFF
    li      x14, 0x00000000FFFFFFFF

=== rt_pc_jump.S ===
// rt_pc_jump.S
//
// Tier-1 fixture: verifies DPC fidelity at the vsim->QEMU2 boundary.
//
// Phase A (QEMU1): slti x0, x0,  0x5A0  -> drain & exit.
// Phase B (vsim):  jump 64 bytes forward, then slti x0, x0,  0x5A1 -> drain.
//                  state_drain captures DPC = PC of insn after the exit marker.
//                  If DPC is stale (e.g., points to the linear PC after the
//                  jump source instead of after the post-jump marker), QEMU2
//                  resumes at the wrong location and never exits cleanly.
// Phase C (QEMU2): semihosting exit with code 0.

#include "semihost_exit.inc"

.section .text
.globl _start
_start:
    slti   x0, x0,  0x5A0                 // QEMU1 drains, exits

    // Phase B: jump forward 0x40 bytes; everything in between is dead code
    // that would set the wrong DPC if the jump were not taken.
    j       phase_b_landing
=== rt_abi_aliases.S ===
// rt_abi_aliases.S
//
// Tier-1 fixture: ra/sp/gp/tp/fp survive QEMU1 -> vsim -> QEMU2 unchanged.
// These ABI-special GPRs are never touched by other Tier-1 fixtures.
//
// Phase A (QEMU1): seed each alias with a distinct page-aligned constant.
// Phase B (vsim):  no-op.
// Phase C (QEMU2): verify; exit code = first mismatching reg num, or 0.

#include "semihost_exit.inc"

.section .text
.globl _start
_start:
    li      ra, 0x00100000
    li      sp, 0x00200000
    li      gp, 0x00300000
    li      tp, 0x00400000
    li      fp, 0x00500000           // x8

    slti   x0, x0,  0x5A0                 // QEMU1 drains, exits

=== rt_all_gprs.S ===
// rt_all_gprs.S
//
// Tier-1 fixture: full sweep of x1..x31 across QEMU1 -> vsim -> QEMU2.
// Each register survives the round-trip with its 64-bit value intact.
//
// Phase A (QEMU1):
//   x5 = 0x00002000 (also serves as Phase C spill base).
//   x_i = 0xA000_0000_0000_0000 + i for i in {1..4, 6..31}.
// Phase B (vsim):  no-op.
// Phase C (QEMU2):
//   Spill x6, x28, x29 (sacrificed below).
//   Verify x_i directly for i in {1..4, 7..27, 30..31, then 5}.
//   Verify spilled x6, x28, x29 against expected.
//   Exit code = first mismatching reg num, or 0 on full pass.

#include "semihost_exit.inc"

.section .text
.globl _start
_start:
    li      x6, 0xA000000000000000   // temp base for ADDI sweep
    addi    x1,  x6, 1

// rt_csr_survival.S
//
// 2-phase guard (L23 + L24): the writable M-mode CSRs round-trip across the
// QEMU1 -> vsim handoff. A value stashed before the ROI is readable inside it
// (ResumeDriver restores the CSR) and a value written inside the ROI is
// captured at drain (StateDrain::drain_with_passthrough re-reads it).
//
// Covered CSRs:
//   L23  mscratch                 -- M-mode software scratch (pure read/write)
//   L24  mepc, mcause, mtval, mie -- writable trap/interrupt CSRs
//
// History: this fixture predates the 2-phase redesign. It used to read the CSRs
// back in a `phase_c` AFTER the exit marker and exit with the index of the
// first mismatch -- but once the QEMU2 handback leg was removed, vsim drains and
// exits AT the exit marker, so phase_c never ran and the guard was silently
// dead. The check now lives INSIDE the ROI, where the vsim leg actually runs.
//
// Two assertion mechanisms:
//   1. In-ROI self-check (works in the plain e2e harness, no --verify): read
//      the CSR back inside the ROI and `bne` against the stashed sentinel,
//      held in a callee-stable GPR which the GPR restore round-trips. On a
//      regressed restore the values differ, so the fixture spins -- vsim never
//      reaches the exit marker, times out, and the harness reports a failure.
//      Used only for mscratch/mepc/mie, whose values round-trip exactly.
//   2. --verify (VERIFY=1): the differential oracle compares the drained CSRs
//      against a pure-QEMU run. Used for mcause (WLRL) and mtval (WARL), whose
//      cross-engine legalisation could differ from a chosen sentinel; the
//      oracle path compares engine-against-engine instead of against a literal.
//
// Not asserted: mip (its pending bits are hardware-driven, not writable via

// vsim-only handoff smoke test. Loads handoff_exit.elf, enables the hybrid
// handoff drain path, runs vsim, and expects:
//   - run() returns EXIT_HANDOFF_TO_QEMU (200)
//   - state.bin is written with valid magic and gpr[12] == 3
// The QEMU spawn half lives in the round-trip e2e test.

#include "cpu_config.hpp"
#include "hybrid/state_abi.h"
#include "platform/platform.hpp"
#include "simulator.hpp"

#include <cci_configuration>
#include <spdlog/sinks/stdout_color_sinks.h>
#include <spdlog/spdlog.h>
#include <systemc>

#include <cstdio>
